new_decomposed = '''    def _decomposed(self, patterns):
        """Inference over per-snapshot programs; None triggers the fallback."""
        inst = self.inst
        S, C, E = self.S, self.C, self.E
        k = self.k
        all_domains = frozenset(self.fault_domains)
        requirements = [all_domains - pattern for pattern in patterns]

        # One program per distinct requirement scope of each snapshot.
        ctx = z3.Context()
        scope_snapshot = []     # snapshot index of each scope
        scope_local = []        # snapshot program of each scope
        scope_prog = []         # program (base + requirements) of each scope
        scope_models = []       # a model of each scope
        scope_bounds = []       # propagated demand bounds of each scope
        scope_row_bounds = []   # aggregated row bounds by coefficient vector
        scope_of = []           # pattern -> snapshot -> scope index
        keys = {}
        for req in requirements:
            per_snap = []
            for si in range(S):
                sig = tuple(sorted(d for d in req
                                   if self.snaps[si].dom_obs.get(d)))
                index = keys.get((si, sig))
                if index is None:
                    local = _Snapshot(inst, si, ctx, 's')
                    formulas = []
                    for d in req:
                        formulas.extend(local.dom_obs.get(d, ()))
                    prog = _Program(ctx)
                    prog.add(local.base)
                    if formulas:
                        prog.add(formulas)
                    # Propagated bounds are implied by the scope's own
                    # constraints; asserting them helps z3 enormously.
                    rows, row_bounds = self._scope_rows(si, req)
                    box = inst.snapshots[si].bounds
                    lo = [b[0] for b in box]
                    hi = [b[1] for b in box]
                    lo, hi = _propagate(rows, lo, hi)
                    for ci in range(C):
                        if lo[ci] > box[ci][0]:
                            prog.add([local.q[ci] >= lo[ci]])
                        if hi[ci] < box[ci][1]:
                            prog.add([local.q[ci] <= hi[ci]])
                    model = prog.model()
                    if model is None:
                        return None
                    index = len(scope_snapshot)
                    keys[(si, sig)] = index
                    scope_snapshot.append(si)
                    scope_local.append(local)
                    scope_prog.append(prog)
                    scope_models.append(model)
                    scope_bounds.append((lo, hi))
                    scope_row_bounds.append(row_bounds)
                per_snap.append(index)
            scope_of.append(per_snap)

        def scope_indices(si):
            return [j for j in range(len(scope_snapshot))
                    if scope_snapshot[j] == si]

        def scope_demands(index):
            return [scope_models[index].eval(v, model_completion=True).as_long()
                    for v in scope_local[index].q]

        # Demand ranges over the union of scopes.
        dmin = [[None] * C for _ in range(S)]
        dmax = [[None] * C for _ in range(S)]
        dmin_at = [[None] * C for _ in range(S)]
        dmax_at = [[None] * C for _ in range(S)]
        for si in range(S):
            indices = scope_indices(si)
            values = {j: scope_demands(j) for j in indices}
            lows = {j: scope_bounds[j][0] for j in indices}
            highs = {j: scope_bounds[j][1] for j in indices}
            for ci in range(C):
                low_all = min(lows[j][ci] for j in indices)
                high_all = max(highs[j][ci] for j in indices)
                best_min = min(values[j][ci] for j in indices)
                best_max = max(values[j][ci] for j in indices)
                argmin = min(indices, key=lambda j: values[j][ci])
                argmax = max(indices, key=lambda j: values[j][ci])
                if best_min > low_all:
                    for j in indices:
                        if values[j][ci] == lows[j][ci]:
                            continue
                        value = scope_prog[j].minimize(scope_local[j].q[ci],
                                                       lows[j][ci], values[j][ci])
                        if value is None:
                            return None
                        if value < best_min:
                            best_min = value
                            argmin = j
                        if best_min == low_all:
                            break
                if best_max < high_all:
                    for j in indices:
                        if values[j][ci] == highs[j][ci]:
                            continue
                        value = scope_prog[j].maximize(scope_local[j].q[ci],
                                                       highs[j][ci], values[j][ci])
                        if value is None:
                            return None
                        if value > best_max:
                            best_max = value
                            argmax = j
                        if best_max == high_all:
                            break
                dmin[si][ci] = best_min
                dmax[si][ci] = best_max
                dmin_at[si][ci] = argmin
                dmax_at[si][ci] = argmax

        # Link load ranges over the union of scopes.
        lmin = [[None] * E for _ in range(S)]
        lmax = [[None] * E for _ in range(S)]
        for si in range(S):
            for j in scope_indices(si):
                local = scope_local[j]
                prog = scope_prog[j]
                demands = scope_demands(j)
                low_demands, high_demands = scope_bounds[j]
                cache = {}
                for ei in range(E):
                    scale, coeffs = inst.edge_coeff[ei]
                    if not any(coeffs):
                        mn = mx = 0
                    else:
                        sig = (scale, tuple(coeffs),
                               scale * inst.edges[ei].capacity)
                        if sig in cache:
                            mn, mx = cache[sig]
                        else:
                            row = scope_row_bounds[j].get(tuple(coeffs),
                                                         [None, None])
                            zlb = 0
                            zub = scale * inst.edges[ei].capacity
                            if row[1] is not None and row[1] < zub:
                                zub = row[1]
                            for ci in range(C):
                                if coeffs[ci]:
                                    zlb += coeffs[ci] * low_demands[ci]
                                    zub += coeffs[ci] * high_demands[ci]
                            if row[0] is not None and row[0] > zlb:
                                zlb = row[0]
                            if zlb > zub:
                                zlb = zub
                            cur = 0
                            for ci in range(C):
                                if coeffs[ci]:
                                    cur += coeffs[ci] * demands[ci]
                            if zlb == zub or cur == zlb:
                                mn = mx = cur
                            elif cur == zub:
                                mn = prog.minimize(local.link[ei], zlb, cur)
                                mx = cur
                            else:
                                mn = prog.minimize(local.link[ei], zlb, cur)
                                mx = prog.maximize(local.link[ei], zub, cur)
                                if mn is None or mx is None:
                                    return None
                            cache[sig] = (mn, mx)
                    if lmin[si][ei] is None or mn < lmin[si][ei]:
                        lmin[si][ei] = mn
                    if lmax[si][ei] is None or mx > lmax[si][ei]:
                        lmax[si][ei] = mx

        # Controller verdicts.
        verdicts = []
        for si in range(S):
            some_agree = False
            some_disagree = False
            for j in scope_indices(si):
                local = scope_local[j]
                prog = scope_prog[j]
                agree, disagree = self._agreement(local, local)
                if C == 0:
                    some_agree = True
                elif not some_agree and prog.sat(agree):
                    some_agree = True
                if C > 0 and not some_disagree:
                    if prog.sat([z3.Or(disagree)]):
                        some_disagree = True
            if some_agree:
                verdicts.append('consistent' if not some_disagree
                                else 'undetermined')
            else:
                verdicts.append('inconsistent')

        # Witness from the first pattern.
        witness_demands = []
        witness_loads = []
        for si in range(S):
            witness_demands.append(scope_demands(scope_of[0][si]))
            witness_loads.append(inst.edge_loads(witness_demands[-1]))
        faulty = self._actual_faults(witness_demands, witness_loads)
        if faulty != patterns[0] or len(faulty) != k:
            return None
        witness = self._witness(witness_demands, witness_loads, faulty)

        unique = all(dmin[i][ci] == dmax[i][ci]
                    for i in range(S) for ci in range(C))

        # A second explanation whose demand matrix differs, when ambiguous.
        alternative = None
        if not unique:
            for i in range(S):
                for ci in range(C):
                    if dmin[i][ci] == dmax[i][ci]:
                        continue
                    if witness_demands[i][ci] != dmin[i][ci]:
                        target, scope = dmin[i][ci], dmin_at[i][ci]
                    else:
                        target, scope = dmax[i][ci], dmax_at[i][ci]
                    chosen = None
                    for pi in range(len(patterns)):
                        if scope_of[pi][i] == scope:
                            chosen = pi
                            break
                    if chosen is None:
                        return None
                    model = scope_prog[scope].model(
                        [scope_local[scope].q[ci] == target])
                    if model is None:
                        return None
                    alt_demands = [None] * S
                    alt_demands[i] = [model.eval(v, model_completion=True).as_long()
                                      for v in scope_local[scope].q]
                    for j in range(S):
                        if j != i:
                            alt_demands[j] = scope_demands(scope_of[chosen][j])
                    alt_loads = [inst.edge_loads(row) for row in alt_demands]
                    alt_faults = self._actual_faults(alt_demands, alt_loads)
                    if alt_faults != patterns[chosen] or len(alt_faults) != k:
                        return None
                    if alt_demands == witness_demands:
                        return None
                    alternative = self._witness(alt_demands, alt_loads, alt_faults)
                    break
                if alternative is not None:
                    break

        forced = set(patterns[0])
        possible = set(patterns[0])
        for pattern in patterns[1:]:
            forced &= pattern
            possible |= pattern

        snapshots = []
        for i in range(S):
            scale_of = [inst.edge_coeff[ei][0] for ei in range(E)]
            snapshots.append({
                'id': inst.snapshots[i].id,
                'demands': [[dmin[i][ci], dmax[i][ci]] for ci in range(C)],
                'links': [[_rat(Fraction(lmin[i][ei], scale_of[ei])),
                           _rat(Fraction(lmax[i][ei], scale_of[ei]))]
                          for ei in range(E)],
                'verdict': verdicts[i],
            })
        return {
            'status': 'unique' if unique else 'ambiguous',
            'min_faults': k,
            'faults': {'forced': sorted(forced), 'possible': sorted(possible)},
            'snapshots': snapshots,
            'witness': witness,
            'alternative': alternative,
        }

'''
